42	        state = false,
43	        type = 'range',
44	        confirm,
45	        cancel,
46	        name,
47	        formulaOrRefString,
48	        comment = '',
49	        localSheetId = SCOPE_WORKBOOK_VALUE_DEFINED_NAME,
50	        hidden = false, // 是否对用户隐藏，与excel兼容，暂时用不上。
51	        id,
52	    } = props;
