79	
80	    const [validString, setValidString] = useState('');
81	
82	    const [typeValue, setTypeValue] = useState(type);
83	
84	    const [validFormulaOrRange, setValidFormulaOrRange] = useState(true);
85	
86	    const options = [{
87	        label: localeService.t('definedName.scopeWorkbook'),
88	        value: SCOPE_WORKBOOK_VALUE_DEFINED_NAME,
89	    }];
90	
91	    const isFormula = (token: string) => {
92	        return !isReferenceStrings(token);
93	    };
94	
95	    useEffect(() => {
96	        setValidFormulaOrRange(true);
97	        setNameValue(name);
98	        setCommentValue(comment);
99	        setLocalSheetIdValue(localSheetId);
100	        let formulaOrRefStringCache = formulaOrRefString;
101	        if (formulaOrRefString.substring(0, 1) === operatorToken.EQUALS) {
102	            setTypeValue('formula');
103	        } else if (isFormula(formulaOrRefString)) {
104	            setTypeValue('formula');
105	            formulaOrRefStringCache = operatorToken.EQUALS + formulaOrRefString;
106	        } else {
107	            setTypeValue('range');
108	        }
109	
110	        setFormulaOrRefStringValue(formulaOrRefStringCache);
111	
112	        setValidString('');
