/**
 * The minimal shape of the services needed to validate a defined name typed in
 * the defined-name box.
 */
export interface IValidateDefinedNameDeps {
    unitId: string;
    name: string;
    workbook: Workbook;
    definedNamesService: {
        getValueByName: (unitId: string, name: string) => Nullable<IDefinedNamesServiceParam>;
    };
    superTableService: {
        hasTable: (name: string) => boolean;
    };
    functionService: {
        hasExecutor: (name: string) => boolean;
    };
}

/**
 * Validate whether a given name is acceptable as a new defined name created from
 * the defined-name box. Returns a locale key describing the problem, or
 * `null` when the name is valid.
 */
export function validateDefinedName(deps: IValidateDefinedNameDeps): string | null | undefined {
    const { unitId, name, workbook, definedNamesService, superTableService, functionService } = deps;

    if (name.length === 0) {
        return 'definedName.nameEmpty';
    }

    // The defined name can't be duplicate with an existing defined name.
    if (definedNamesService.getValueByName(unitId, name) != null) {
        return 'definedName.nameDuplicate';
    }

    // The defined name can't be duplicate with an existing table name.
    if (superTableService.hasTable(name)) {
        return 'definedName.nameDuplicate';
    }

    // The defined name can't be a reference string with effective column, which will cause confusion.
    if (
        !Tools.isValidParameter(name) ||
        isReferenceStringWithEffectiveColumn(name) ||
        (!Tools.isStartValidPosition(name) && !hasCJKText(name.substring(0, 1)))
    ) {
        return 'definedName.nameInvalid';
    }

    // The defined name can't be duplicate with an existing sheet name.
    const worksheets = workbook.getSheets();
    if (worksheets.some((sheet) => sheet.getName() === name)) {
        return 'definedName.nameSheetConflict';
    }

    // The defined name can't be duplicate with an existing function name.
    if (functionService.hasExecutor(name.toUpperCase())) {
        return 'definedName.nameConflict';
    }

    return null;
}

export type IDefinedNameBoxAction =
    | { type: 'focusDefinedName'; definedName: IDefinedNamesServiceParam }
    | { type: 'focusSelection'; refString: string }
    | { type: 'createDefinedName'; name: string }
    | { type: 'reset' };

export interface IResolveDefinedNameBoxActionDeps extends IValidateDefinedNameDeps {
    inputValue: string;
    rangeString: string;
}

/**
 * Determine the action to take when the user confirms (presses Enter) the value
 * typed in the defined-name box.
 */
export function resolveDefinedNameBoxAction(deps: IResolveDefinedNameBoxActionDeps): IDefinedNameBoxAction {
    const { unitId, workbook, definedNamesService, superTableService, functionService, inputValue } = deps;

    // The value matches an existing defined name (case-insensitively).
    const definedName = definedNamesService.getValueByName(unitId, inputValue);
    if (definedName) {
        return { type: 'focusDefinedName', definedName };
    }

    // The value is a cell or range reference.
    if (isReferenceStringWithEffectiveColumn(inputValue)) {
        return { type: 'focusSelection', refString: inputValue };
    }

    // The value is a brand new name that doesn't conflict with anything.
    const validationResult = validateDefinedName({
        unitId,
        name: inputValue,
        workbook,
        definedNamesService,
        superTableService,
        functionService,
    });
    if (validationResult == null) {
        return { type: 'createDefinedName', name: inputValue };
    }

    // The value is invalid (e.g. conflicts with a sheet name).
    return { type: 'reset' };
}

/**
 * Build an absolute reference string (e.g. `Sheet1!$A$1` / `Sheet1!$B$2:$C$4`)
 * for the active sheet from the given selections.
 */
export function getAbsoluteRefStringFromSelection(
    workbook: Workbook,
    selections: ISelectionWithStyle[],
    refStringService: {
        convertRefersToAbsolute: (
            refString: string,
            rowAbsType: AbsoluteRefType,
            colAbsType: AbsoluteRefType,
            sheetName: string
        ) => string;
    }
): string {
    const worksheet = workbook.getActiveSheet();
    const sheetName = worksheet.getName();
    const { range } = selections[0];
    const { startRow, startColumn, endRow, endColumn } = range;

    const startRefString = `${Tools.chatAtABC(startColumn)}${startRow + 1}`;

    let refString: string;
    if (startRow === endRow && startColumn === endColumn) {
        refString = `${sheetName}!${startRefString}`;
    } else {
        const endRefString = `${Tools.chatAtABC(endColumn)}${endRow + 1}`;
        refString = `${sheetName}!${startRefString}:${endRefString}`;
    }

    return refStringService.convertRefersToAbsolute(refString, AbsoluteRefType.ALL, AbsoluteRefType.ALL, sheetName);
}

